import 'dart:io';

Future<void> main() async {
  // Scenario 1: client aborts mid-REQUEST-body.
  final server = await HttpServer.bind('127.0.0.1', 0);
  final errors = <Object>[];
  server.listen((request) async {
    final body = await utf8.decoder.bind(request).join();
    stdout.writeln('handler got body: $body');
    request.response.write('ok');
    await request.response.close();
  });
  final s = await Socket.connect('127.0.0.1', server.port);
  const partial = '{"model": "test-model"';
  s.write('POST /v1/chat/completions HTTP/1.1\r\n'
      'Host: 127.0.0.1\r\n'
      'Content-Type: application/json\r\n'
      'Content-Length: ${partial.length + 512}\r\n'
      '\r\n'
      '$partial');
  await s.flush();
  await Future<void>.delayed(const Duration(milliseconds: 50));
  s.destroy();
  await Future<void>.delayed(const Duration(milliseconds: 300));
  stdout.writeln('--- scenario 1 settle; now closing server');
  await server.close(force: true);

  // Scenario 2: client aborts mid-RESPONSE-stream.
  final server2 = await HttpServer.bind('127.0.0.1', 0);
  server2.listen((request) async {
    await utf8.decoder.bind(request).join();
    request.response.headers.contentType =
        ContentType('text', 'event-stream');
    for (var i = 0; i < 20; i++) {
      request.response.write('data: chunk$i\n\n');
      await request.response.flush();
      await Future<void>.delayed(const Duration(milliseconds: 60));
    }
    await request.response.close();
  });
  final s2 = await Socket.connect('127.0.0.1', server2.port);
  const body2 = '{}';
  s2.write('POST /v1/chat/completions HTTP/1.1\r\n'
      'Host: 127.0.0.1\r\n'
      'Content-Type: application/json\r\n'
      'Content-Length: ${body2.length}\r\n'
      '\r\n'
      '$body2');
  // Read the first chunk, then stop reading and destroy (unread data → RST).
  final first = await s2.first.timeout(const Duration(seconds: 3));
  stdout.writeln('client got first chunk: ${utf8.decode(first)}');
  await Future<void>.delayed(const Duration(milliseconds: 100));
  s2.destroy();
  await Future<void>.delayed(const Duration(seconds: 2));
  stdout.writeln('--- scenario 2 settle');
  await server2.close(force: true);
  stdout.writeln('unhandled errors observed: $errors');
}

