    for (var i = 0; i < 20; i++) {
      request.response.write('data: chunk$i\n\n');
      await request.response.flush();
      await Future<void>.delayed(const Duration(milliseconds: 60));
    }
    await request.response.close();
  });
  final s2 = await Socket.connect('127.0.0.1', server2.port);
  const body2 = '{}';
  s2.write('POST /v1/chat/completions HTTP/1.1\r\n'
      'Host: 127.0.0.1\r\n'
      'Content-Type: application/json\r\n'
      'Content-Length: ${body2.length}\r\n'
      '\r\n'
      '$body2');
  final first = await s2.first.timeout(const Duration(seconds: 3));
  print('client got first chunk: ${utf8.decode(first)}');
  await Future<void>.delayed(const Duration(milliseconds: 100));
  s2.destroy();
  await Future<void>.delayed(const Duration(seconds: 2));
  print('--- settled without unhandled error');
  await server2.close(force: true);
}

