import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

import 'fa_cli_fixtures.dart';

void main() {
  test(
    'MockOpenAiServer: a client abort mid-request leaks no unhandled error',
    () async {
